// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    EmergencyOracleFactory c;
    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != c.jojoTeam());

        bool ok;
        vm.prank(caller);
        try c.newEmergencyOracle("test") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "non-jojoTeam caller should not succeed in newEmergencyOracle");
    }
}
